import{_ as t,o as n,c as a,a2 as i}from"./chunks/framework.z3u3TMv0.js";const p=JSON.parse('{"title":"In MiniTavern konfigurieren","description":"MiniTavern mit Ollama, LM Studio, KoboldCPP, llama.cpp — Einstellungen → Modellverbindung, OpenAI-kompatible Base URL und Test.","frontmatter":{"title":"In MiniTavern konfigurieren","description":"MiniTavern mit Ollama, LM Studio, KoboldCPP, llama.cpp — Einstellungen → Modellverbindung, OpenAI-kompatible Base URL und Test.","head":[["meta",{"name":"keywords","content":"Tavern,AI Tavern,MiniTavern,AI Begleiter,AI Freund,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobil,Silly Tavern Android,Silly Tavern iOS,AI Roleplay,Charakterkarte,AI Chat,mobiles AI,Offline-AI,AI Geschichte,lokales LLM,Ollama,LM Studio,Lorebook,Regex,BYOK,Handbuch,Anleitung"}],["meta",{"property":"og:title","content":"In MiniTavern konfigurieren · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern mit Ollama, LM Studio, KoboldCPP, llama.cpp — Einstellungen → Modellverbindung, OpenAI-kompatible Base URL und Test."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/de/connect-app/minitavern"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/de/connect-app/minitavern"}]]},"headers":[],"relativePath":"de/connect-app/minitavern.md","filePath":"de/connect-app/minitavern.md","lastUpdated":1787224147000}'),l={name:"de/connect-app/minitavern.md"};function r(d,e,o,s,u,c){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="in-minitavern-konfigurieren" tabindex="-1">In MiniTavern konfigurieren <a class="header-anchor" href="#in-minitavern-konfigurieren" aria-label="Permalink to &quot;In MiniTavern konfigurieren&quot;">​</a></h1><p>App-Pfad: <strong>Einstellungen → Modelle → Modellverbindung</strong>.</p><h2 id="neue-verbindung" tabindex="-1">Neue Verbindung <a class="header-anchor" href="#neue-verbindung" aria-label="Permalink to &quot;Neue Verbindung&quot;">​</a></h2><ol><li>MiniTavern → unten <strong>Einstellungen</strong>.</li><li><strong>Modelle</strong> → <strong>Modellverbindung</strong>.</li><li>Oben rechts <strong>Neu</strong>.</li><li><strong>Modellplattform</strong> → <strong>Custom</strong> (OpenAI-kompatibel / eigene Base URL, App-Text gilt).</li><li>Tabelle unten ausfüllen, speichern; mit <strong>Testen</strong> vor dem Standard setzen.</li></ol><h2 id="beispiele-je-tool" tabindex="-1">Beispiele je Tool <a class="header-anchor" href="#beispiele-je-tool" aria-label="Permalink to &quot;Beispiele je Tool&quot;">​</a></h2><p><code>YOUR_PC_IP</code> = LAN-IP des PCs (kein <code>localhost</code>).</p><table tabindex="0"><thead><tr><th>Tool</th><th>Base-URL-Beispiel</th><th>Modellname</th><th>API Key</th></tr></thead><tbody><tr><td><a href="/ultra_guides/de/ollama/lan">Ollama</a></td><td><code>http://YOUR_PC_IP:11434/v1</code></td><td>Name aus <code>ollama list</code></td><td>leer oder <code>ollama</code></td></tr><tr><td><a href="/ultra_guides/de/lmstudio/server">LM Studio</a></td><td><code>http://YOUR_PC_IP:1234/v1</code></td><td>id im Local Server</td><td>leer</td></tr><tr><td><a href="/ultra_guides/de/koboldcpp/server">KoboldCPP</a></td><td><code>http://YOUR_PC_IP:5001/v1</code></td><td>id aus <code>/v1/models</code></td><td>leer</td></tr><tr><td><a href="/ultra_guides/de/llamacpp/server">llama.cpp</a></td><td><code>http://YOUR_PC_IP:8080/v1</code></td><td>id vom Server</td><td>leer</td></tr><tr><td><a href="/ultra_guides/de/localai/install">LocalAI</a></td><td><code>http://YOUR_PC_IP:8080/v1</code></td><td>LocalAI-Konfigname</td><td>je nach Auth</td></tr><tr><td><a href="/ultra_guides/de/jan/install">Jan</a></td><td>Adresse auf der API-Seite</td><td>id aus der Liste</td><td>laut App</td></tr><tr><td><a href="/ultra_guides/de/textgen/install">text-generation-webui</a></td><td><code>http://YOUR_PC_IP:Port/v1</code></td><td>id der Extension</td><td>laut Extension</td></tr></tbody></table><p>Alias frei, z. B. <code>Zuhause-Ollama</code>, <code>Büro-Kobold</code>.</p><h2 id="als-standard-und-chatten" tabindex="-1">Als Standard und chatten <a class="header-anchor" href="#als-standard-und-chatten" aria-label="Permalink to &quot;Als Standard und chatten&quot;">​</a></h2><ol><li>In der Liste als <strong>Standard</strong>.</li><li>Charakterkarte importieren/wählen, Nachricht senden.</li><li>Am PC sollte Aktivität sichtbar sein; in der App Streaming oder volle Antwort.</li></ol><h2 id="sitzungsubersteuerung-optional" tabindex="-1">Sitzungsübersteuerung (optional) <a class="header-anchor" href="#sitzungsubersteuerung-optional" aria-label="Permalink to &quot;Sitzungsübersteuerung (optional)&quot;">​</a></h2><p>Temporär anderes lokales Modell: in Chat-Einstellungen globale Defaults überschreiben.</p><h2 id="hinweise" tabindex="-1">Hinweise <a class="header-anchor" href="#hinweise" aria-label="Permalink to &quot;Hinweise&quot;">​</a></h2><ul><li>Auf dem Handy <strong>kein</strong> <code>http://localhost:…</code> / <code>http://127.0.0.1:…</code>.</li><li>URL endet auf <code>/v1</code>, nicht <code>/chat/completions</code>.</li><li>Schlaf, Deckel, Netzwechsel können die IP ändern.</li><li>Ports laut tatsächlich laufendem Dienst; Tabelle = übliche Defaults.</li></ul><p>Keine Verbindung: <a href="/ultra_guides/de/troubleshoot">Fehlerbehebung</a>. Toolwahl: <a href="/ultra_guides/de/local/tools">Tool-Übersicht</a>.</p>',15)])])}const g=t(l,[["render",r]]);export{p as __pageData,g as default};
